text:
{
  "osszkep": "A szöveg felépítése logikus és barátságos, de helyenként kissé rideg, sűrített vagy ügyintézői hangvételű. Néhány mondat gördülékenyebbé tételével természetesebb, nyugodt és megbízható beszédhang érhető el.",
  "javaslatok": [
    {
      "id": "L01",
      "gond": "Kissé gépies nyitás; a szabályzat szerint a kifejezés 'az alkalmazás', nem pedig 'az alkalmazásunkat'.",
      "uj_szoveg": "Örülünk, hogy letöltötted az alkalmazást!"
    },
    {
      "id": "L03",
      "gond": "A 'valódi könyvelőd lesz' kissé reklámosan és kétkedést keltően hangzik, a 'segít' vagy 'vigyáz rád' hangulat melegebb.",
      "uj_szoveg": "Saját könyvelőd lesz, aki kézben tartja az adóügyeidet."
    },
    {
      "id": "L05",
      "gond": "A 'mikorra és hova fizess' szófordulat beszédben kissé darabos és túl feszes.",
      "uj_szoveg": "A Főoldalon mindig látod, mikor, hova és mennyit kell utalnod."
    },
    {
      "id": "L07",
      "gond": "A 'A bekötés néhány lépés' magyartalan, tőmondatos szerkezet. A 'mi ez' szintén túl rideg.",
      "uj_szoveg": "A beállítás csak néhány lépés. Mindegyiknél pontosan elmagyarázzuk, mit kell tenned."
    },
    {
      "id": "L09",
      "gond": "A 'te magad jelented be' hangsúlyozása feleslegesen riasztó lehet egy kezdőnek, mintha magára hagynánk.",
      "uj_szoveg": "Ha még nincs vállalkozásod, a NAV-nál indíthatod el, nagyjából negyedóra alatt."
    },
    {
      "id": "L11",
      "gond": "Túl sok információ és feltétel került egyetlen mondatba, beszédben nehezen követhető.",
      "uj_szoveg": "Ezután elfogadod a szerződést, és megadod a bankkártyádat a havidíjhoz. Új vállalkozásnál erre csak az adószámod után lesz szükség."
    },
    {
      "id": "L16",
      "gond": "A 'törvény szerint azonosítanunk kell téged' túlzottan hatósági, rideg megfogalmazás.",
      "uj_szoveg": "Erre a törvényi előírások miatt van szükség, hogy biztonságban legyenek az adataid."
    },
    {
      "id": "L18",
      "gond": "A 'funkció még nem érhető el' informatikai szakzsargon, nem illik a privátbanki közvetlenséghez.",
      "uj_szoveg": "Addig néhány dolgot még nem érsz el, de amint elkészül, minden megnyílik előtted."
    },
    {
      "id": "L20",
      "gond": "A '24–48 óra' lassúnak hat és távolságtartó, kimondva nehézkes. Élőbeszédben a napokban megadott időtartam természetesebb.",
      "uj_szoveg": "Ha elakadsz, kérj bátran visszahívást, és csapatunk egy-két munkanapon belül felhív."
    }
  ]
}
